//! One SQLite table per persisted list: by default the record type's own
//! (`#[table(name)]`), or another one chosen for a second list of that type.
mod schema;

use crate::{Error, Result};
#[doc(hidden)]
pub use rusqlite;
use rusqlite::{Connection, OptionalExtension, Row, ToSql, params_from_iter};
pub use schema::{Column, ColumnType, PrimaryKey};
use std::{
    path::Path,
    sync::{Arc, Mutex},
};

/// Generated by `#[derive(homeport_runtime::Table)]`. Column order is used for bound parameters.
pub trait Table: Sized {
    type Key: ToSql + ?Sized;
    const NAME: &'static str;
    const KEY: &'static str;
    const COLUMNS: &'static [Column];
    fn values(&self) -> Vec<&dyn ToSql>;
    fn key(&self) -> &Self::Key;
    fn from_row(row: &Row<'_>) -> rusqlite::Result<Self>;
}

#[derive(Clone)]
pub struct Store {
    conn: Arc<Mutex<Connection>>,
}
pub struct Tx<'a> {
    conn: &'a Connection,
}
fn db(e: rusqlite::Error) -> Error {
    Error::new("storage", format!("Database operation failed: {e}"))
}
fn quoted(name: &str) -> String {
    format!("\"{}\"", name.replace('"', "\"\""))
}
fn columns<T: Table>() -> String {
    T::COLUMNS
        .iter()
        .map(|c| quoted(c.name))
        .collect::<Vec<_>>()
        .join(", ")
}
fn insert_sql<T: Table>(table: &str) -> String {
    let args = vec!["?"; T::COLUMNS.len()].join(", ");
    format!(
        "INSERT INTO {} ({}) VALUES ({args})",
        quoted(table),
        columns::<T>()
    )
}

/// For migration scripts and presets: `env('NAME')` is the environment
/// variable (empty when unset), `new_id()` a new random id.
fn functions(conn: &Connection) -> rusqlite::Result<()> {
    use rusqlite::functions::FunctionFlags;
    conn.create_scalar_function("env", 1, FunctionFlags::SQLITE_UTF8, |cx| {
        let name: String = cx.get(0)?;
        Ok(std::env::var(name).unwrap_or_default())
    })?;
    conn.create_scalar_function("new_id", 0, FunctionFlags::SQLITE_UTF8, |_| {
        Ok(crate::Id::random().to_string())
    })
}

impl Store {
    pub fn open(path: impl AsRef<Path>) -> Result<Self> {
        let conn = Connection::open(path).map_err(db)?;
        conn.pragma_update(None, "trusted_schema", false)
            .map_err(db)?;
        functions(&conn).map_err(db)?;
        Ok(Self {
            conn: Arc::new(Mutex::new(conn)),
        })
    }
    /// Write a consistent copy of the whole database to `path` (must not exist).
    pub fn backup_to(&self, path: &Path) -> Result<()> {
        let conn = self
            .conn
            .lock()
            .map_err(|_| Error::new("storage", "Database lock poisoned"))?;
        let target = path
            .to_str()
            .ok_or_else(|| Error::msg("Backup path is not valid UTF-8."))?;
        conn.execute("VACUUM INTO ?1", [target]).map_err(db)?;
        Ok(())
    }
    /// Replace the whole database with the copy at `path`. The copy must be an
    /// homeport database; nothing changes when it is not.
    pub fn restore_from(&self, path: &Path) -> Result<()> {
        Self::check_configuration(path)?;
        let src = Connection::open_with_flags(path, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY)
            .map_err(db)?;
        let mut conn = self
            .conn
            .lock()
            .map_err(|_| Error::new("storage", "Database lock poisoned"))?;
        rusqlite::backup::Backup::new(&src, &mut conn)
            .and_then(|b| b.run_to_completion(256, std::time::Duration::ZERO, None))
            .map_err(db)
    }
    pub(crate) fn check_configuration(path: &Path) -> Result<()> {
        let conn = Connection::open_with_flags(path, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY)
            .map_err(db)?;
        conn.pragma_update(None, "trusted_schema", false)
            .map_err(db)?;
        let ours: bool = conn.query_row("SELECT count(*) = 1 FROM sqlite_schema WHERE type = 'table' AND name = 'kernel_plugins'", [], |r| r.get(0)).map_err(db)?;
        let safe: bool = conn.query_row("SELECT count(*) = 0 FROM sqlite_schema WHERE type NOT IN ('table', 'index') OR upper(sql) LIKE '%VIRTUAL TABLE%'", [], |r| r.get(0)).map_err(db)?;
        let integrity: String = conn
            .query_row("PRAGMA quick_check", [], |r| r.get(0))
            .map_err(db)?;
        if !ours || !safe || integrity != "ok" {
            return Err(Error::msg(
                "This file is not a valid homeport configuration. Your settings have not changed.",
            ));
        }
        Ok(())
    }
    /// Check that migration scripts created `T`'s table as the type declares it.
    pub fn check<T: Table>(&self) -> Result<()> {
        self.check_in::<T>(T::NAME)
    }
    /// [`Self::check`] for rows of `T` kept in another table.
    pub fn check_in<T: Table>(&self, table: &str) -> Result<()> {
        let conn = self
            .conn
            .lock()
            .map_err(|_| Error::new("storage", "Database lock poisoned"))?;
        schema::verify::<T>(&conn, table)
    }
    /// A failing closure rolls back every change. Keep network I/O outside it.
    pub fn transaction<T>(&self, f: impl FnOnce(&Tx<'_>) -> Result<T>) -> Result<T> {
        let mut conn = self
            .conn
            .lock()
            .map_err(|_| Error::new("storage", "Database lock poisoned"))?;
        let tx = conn.transaction().map_err(db)?;
        let api = Tx { conn: &tx };
        let out = f(&api)?;
        tx.commit().map_err(db)?;
        Ok(out)
    }
}
impl Tx<'_> {
    pub fn put<T: Table>(&self, record: &T) -> Result<()> {
        self.put_in(T::NAME, record)
    }
    pub fn put_in<T: Table>(&self, table: &str, record: &T) -> Result<()> {
        let updates: Vec<_> = T::COLUMNS
            .iter()
            .filter(|c| c.name != T::KEY)
            .map(|c| {
                let name = quoted(c.name);
                format!("{name}=excluded.{name}")
            })
            .collect();
        let action = if updates.is_empty() {
            String::from("NOTHING")
        } else {
            format!("UPDATE SET {}", updates.join(", "))
        };
        let sql = format!(
            "{} ON CONFLICT ({}) DO {action}",
            insert_sql::<T>(table),
            quoted(T::KEY)
        );
        self.conn
            .prepare_cached(&sql)
            .map_err(db)?
            .execute(params_from_iter(record.values()))
            .map_err(db)?;
        Ok(())
    }
    pub fn get<T: Table>(&self, id: &T::Key) -> Result<Option<T>> {
        let sql = format!(
            "SELECT {} FROM {} WHERE {} = ?",
            columns::<T>(),
            quoted(T::NAME),
            quoted(T::KEY)
        );
        self.conn
            .prepare_cached(&sql)
            .map_err(db)?
            .query_row([&id], T::from_row)
            .optional()
            .map_err(db)
    }
    pub fn latest<T: Table>(&self, limit: u32) -> Result<Vec<T>> {
        let sql = format!(
            "SELECT {} FROM {} ORDER BY _rowid_ DESC LIMIT ?",
            columns::<T>(),
            quoted(T::NAME)
        );
        let mut stmt = self.conn.prepare_cached(&sql).map_err(db)?;
        let rows = stmt.query_map([limit], T::from_row).map_err(db)?;
        rows.collect::<rusqlite::Result<_>>().map_err(db)
    }
    /// All rows in insertion order.
    pub fn all<T: Table>(&self) -> Result<Vec<T>> {
        self.all_in(T::NAME)
    }
    pub fn all_in<T: Table>(&self, table: &str) -> Result<Vec<T>> {
        let sql = format!(
            "SELECT {} FROM {} ORDER BY _rowid_",
            columns::<T>(),
            quoted(table)
        );
        let mut stmt = self.conn.prepare_cached(&sql).map_err(db)?;
        let rows = stmt.query_map([], T::from_row).map_err(db)?;
        rows.collect::<rusqlite::Result<_>>().map_err(db)
    }
    /// Raw SQL for migrations and custom persistence.
    pub fn sql(&self) -> &Connection {
        self.conn
    }
    pub fn delete<T: Table>(&self, id: &T::Key) -> Result<bool> {
        self.delete_in::<T>(T::NAME, id)
    }
    pub fn delete_in<T: Table>(&self, table: &str, id: &T::Key) -> Result<bool> {
        let sql = format!("DELETE FROM {} WHERE {} = ?", quoted(table), quoted(T::KEY));
        let removed = self
            .conn
            .prepare_cached(&sql)
            .map_err(db)?
            .execute([&id])
            .map_err(db)?
            > 0;
        Ok(removed)
    }
}
